def decode_from_zwc(zwc_text):
    bit_map = { '\u200b': '0', '\u200c': '1' }
    bits = ''.join(bit_map.get(ch, '') for ch in zwc_text)
    bytes_list = [bits[i:i+8] for i in range(0, len(bits), 8)]
    return bytes(int(b, 2) for b in bytes_list).decode()
    
    
